def formatGenerated(iso: Any = js.UNDEF) -> Any:
    if not js.truthy(iso):
        return ""
    d: Any = parseTimestamp(iso)
    if js.is_nan(d.get_time()):
        return iso

    def p(n: Any) -> Any:
        return js.pad_start(js.s(n), 2, "0")

    return (
        js.s(d.utc_year())
        + "-"
        + js.s(p(js.add(d.utc_month(), 1)))
        + "-"
        + js.s(p(d.utc_date()))
        + " "
        + js.s(p(d.utc_hours()))
        + ":"
        + js.s(p(d.utc_minutes()))
        + " UTC"
    )


def munthaBand(house: Any) -> Any:
    _case1: Any = house
    if js.same(_case1, 1) or js.same(_case1, 5) or js.same(_case1, 9):
        return "favorable"
    elif js.same(_case1, 6) or js.same(_case1, 8) or js.same(_case1, 12):
        return "challenging"
    else:
        return "mixed"


