def renderVarshaphalHtml(data: Any, branding: Any = js.UNDEF) -> Any:
    data = withoutNullItems({**data, "Locale": safeLocale(js.get(data, "Locale"))})
    resolved: Any = resolveBranding(js.get(data, "Branding"), branding)
    t: Any = makeLabeler(LABELS, js.get(data, "Locale"))
    loc: Any = (
        js.get(data, "Locale")
        if (js.truthy(js.get(data, "Locale")) and js.truthy(own(LABELS, js.get(data, "Locale"))))
        else "en"
    )
    subject: Any = js.nullish(js.get(data, "Subject"), {})
    asc: Any = js.nullish(js.get(data, "Ascendant"), {})
    muntha: Any = js.nullish(js.get(data, "Muntha"), {})
    lord: Any = js.nullish(js.get(data, "VarshaLord"), {})
    planets: Any = js.get(data, "Planets") if js.is_array(js.get(data, "Planets")) else []
    year: Any = (
        js.get(data, "TargetYear") if (js.type_of(js.get(data, "TargetYear")) == "number") else 0
    )
    coverMeta: Any = (
        esc(t("born"))
        + " "
        + esc(js.get(subject, "BirthDate"))
        + " "
        + esc(t("at"))
        + " "
        + esc(js.get(subject, "BirthTime"))
        + "<br>"
        + esc(js.get(subject, "BirthPlace"))
    )
    cover: Any = (
        ('<section class="cover">\n  ')
        + js.s(coverBrandingHtml(resolved))
        + ("\n  <h1>")
        + esc(t("title_varsha"))
        + ('</h1>\n  <div class="year-badge">')
        + esc(js.get(data, "TargetYear"))
        + ('</div>\n  <div class="subject">')
        + esc(js.get(subject, "Name"))
        + ('</div>\n  <div class="meta">')
        + js.s(coverMeta)
        + ('</div>\n  <div class="generated">')
        + esc(t("generated"))
        + " "
        + esc(formatGenerated(js.get(data, "GeneratedAt")))
        + ("</div>\n</section>")
    )
    solarReturn: Any = (
        "<h2>"
        + esc(t("section_solar_return"))
        + ("</h2>\n<p>\n  <strong>")
        + esc(t("solar_return_at"))
        + ":</strong> "
        + esc(
            (
                _v2
                if js.truthy(_v2 := js.get(data, "SolarReturnLocal"))
                else formatGenerated(js.get(data, "SolarReturnISO"))
            )
        )
        + ("<br>\n  <strong>")
        + esc(t("ascendant"))
        + (":</strong>\n  ")
        + esc(js.get(asc, "sign"))
        + " ("
        + esc(js.get(asc, "dms_within"))
        + (") —\n  ")
        + esc(t("nakshatra"))
        + ": "
        + esc(js.get(asc, "nakshatra"))
        + (",\n  ")
        + esc(t("pada"))
        + " "
        + esc(js.get(asc, "pada"))
        + ("\n</p>")
    )
    indicators: Any = (
        ('<div class="indicator-grid">\n  <div class="indicator-card">\n    <div class="label">')
        + esc(t("muntha"))
        + ('</div>\n    <div class="value">')
        + esc(js.get(muntha, "sign"))
        + ('</div>\n    <div class="detail">')
        + esc(t("house"))
        + " "
        + esc(js.get(muntha, "house"))
        + " "
        + esc(t("from_natal_lagna"))
        + ('</div>\n  </div>\n  <div class="indicator-card">\n    <div class="label">')
        + esc(t("varsha_lord"))
        + ('</div>\n    <div class="value">')
        + esc(js.get(lord, "name"))
        + ('</div>\n    <div class="detail">')
        + esc(t("hora_number"))
        + " "
        + esc(js.get(lord, "hora"))
        + ("</div>\n  </div>\n</div>")
    )

    def _fn3(pl: Any) -> Any:
        p: Any = js.nullish(js.get(pl, "placement"), {})
        retro: Any = " (R)" if js.truthy(js.get(pl, "retro")) else ""
        return (
            "<tr><td>"
            + esc(js.get(pl, "name"))
            + js.s(retro)
            + "</td><td>"
            + esc(js.get(p, "sign"))
            + "</td><td>"
            + esc(js.get(p, "dms_within"))
            + "</td><td>"
            + esc(js.get(pl, "house_num"))
            + "</td><td>"
            + esc(js.get(p, "nakshatra"))
            + " ("
            + esc(js.get(p, "pada"))
            + ")</td></tr>"
        )

    planetRows: Any = js.join(js.map_(planets, _fn3), "")
    planetsTable: Any = (
        "<h2>"
        + esc(t("section_planets_sr"))
        + ("</h2>\n<table>\n  <thead>\n    <tr>\n      <th>")
        + esc(t("planet"))
        + ("</th>\n      <th>")
        + esc(t("sign"))
        + ("</th>\n      <th>")
        + esc(t("degree"))
        + ("</th>\n      <th>")
        + esc(t("house"))
        + ("</th>\n      <th>")
        + esc(t("nakshatra"))
        + ("</th>\n    </tr>\n  </thead>\n  <tbody>")
        + js.s(planetRows)
        + ("</tbody>\n</table>")
    )
    munthaHouse: Any = (
        js.get(muntha, "house") if (js.type_of(js.get(muntha, "house")) == "number") else 0
    )
    outlook: Any = (
        "<h2>"
        + esc(t("section_outlook"))
        + ("</h2>\n<p>")
        + esc(outlookText(loc, year, munthaBand(munthaHouse), munthaHouse))
        + "</p>"
    )
    bodyHtml: Any = js.join([cover, solarReturn, indicators, planetsTable, outlook], ("\n\n"))
    return layoutDocument(
        {
            "lang": js.get(data, "Locale"),
            "title": (
                js.s(t("title_varsha"))
                + " "
                + js.s(js.nullish(js.get(data, "TargetYear"), ""))
                + " — "
                + js.s(js.nullish(js.get(subject, "Name"), ""))
            ),
            "branding": resolved,
            "bodyHtml": bodyHtml,
            "extraCss": EXTRA_CSS,
        }
    )
